import {ShiftSession,portrait} from './shift-session.mjs?v=1.1.0';
import {installationSummary} from './career-core.mjs?v=1.1.0';
import {LEADS,LOCATIONS,ROLE_INFO,createInstallation,applyAction,inspectWire,restoreInstallation,hashCase} from './lt32-core.mjs?v=1.1.0';
import {carSvg,trackerSvg} from './lt32-car.mjs?v=1.1.0';
const app=document.querySelector('#lt32-app'),modal=document.querySelector('#lt32-modal');
let desk=null,deskTick=performance.now(),state=null,context=null,booted=false,showFired=false,failTimeout=0,failInterval=0,toastTimeout=0,drag=null,focusBefore=null,ignoreClickUntil=0;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
const stages=['Escolher local','Ligar os fios','Esconder','Fechar'];
const stageIndex=()=>({location:0,wiring:1,hiding:2,closing:3,success:4,explosion:0}[state.phase]);
const tellParent=(event,payload={})=>{if(parent!==window)parent.postMessage({type:'andersons-workshop',event,payload},location.origin);};
const key=()=>context?.mode==='lt32-free'?'andersons-lt32-solo-v1':'andersons-lt32-campaign-v1';
function save(){if(!state||state.phase==='explosion')return;try{localStorage.setItem(key(),JSON.stringify(state));}catch{}}
function toast(text){const el=$('#lt32-toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),2700);}
const audio={ctx:null,init(){if(context?.prefs?.sound===false)return;try{this.ctx??=new(window.AudioContext||window.webkitAudioContext)();this.ctx.resume().catch(()=>{});}catch{}},tick(win=false){this.init();if(!this.ctx||context?.prefs?.sound===false)return;const now=this.ctx.currentTime;for(let i=0;i<(win?3:1);i++){const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type='triangle';o.frequency.value=(win?[392,494,659][i]:740);g.gain.setValueAtTime(.025,now+i*.11);g.gain.exponentialRampToValueAtTime(.0001,now+i*.11+.18);o.connect(g);g.connect(this.ctx.destination);o.start(now+i*.11);o.stop(now+i*.11+.2);}},boom(){this.init();if(!this.ctx||context?.prefs?.sound===false)return;try{const len=this.ctx.sampleRate*.9,buffer=this.ctx.createBuffer(1,len,this.ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<len;i++)data[i]=(Math.random()*2-1)*(1-i/len);const source=this.ctx.createBufferSource(),filter=this.ctx.createBiquadFilter(),gain=this.ctx.createGain();source.buffer=buffer;filter.type='lowpass';filter.frequency.value=650;gain.gain.value=.2;source.connect(filter);filter.connect(gain);gain.connect(this.ctx.destination);source.start();}catch{}}};
function header(){return `<header class="topbar"><a class="brand" href="./" data-action="menu"><b>A</b> OS ANDERSONS</a><span class="top-label">${context.mode==='lt32-free'?'MINIGAME':'ATO 02'} / INSTALAÇÃO LT-32 PRO</span><nav><button data-action="sound" class="compact">${context.prefs?.sound===false?'Som desligado':'Som ligado'}</button><button data-action="help" class="compact">Guia rápido</button><button data-action="menu" class="compact">Menu do jogo</button></nav></header>`;}
function progress(){const index=stageIndex();return `<nav class="progress" aria-label="Etapas da instalação">${stages.map((title,i)=>`<span class="step ${index===i?'current':index>i?'done':''}" ${index===i?'aria-current="step"':''}><b>${index>i?'✓':i+1}</b><span>${title}</span></span>`).join('')}</nav>`;}
function sidebar(){const place=LOCATIONS.find(l=>l.id===state.location),tips={location:['O PAINEL ESTÁ PROIBIDO, ANDERSON.','Escolha um ponto discreto sob acabamento plástico. Os dois pontos laterais aprovados deste veículo fictício não têm metal cobrindo a antena.'],wiring:['LEIA O CABO. NÃO VÁ SÓ PELA COR.','Toque em um dos cabos A–L para examinar o sinal. Depois toque no fio correspondente do chicote do LT-32 PRO. Também pode arrastar entre as pontas.'],hiding:['ESCONDER NÃO É LARGAR DE QUALQUER JEITO.','Vire o aparelho: a face sem adesivo fica para cima. Fixe o rastreador e isole as emendas. Depois guarde no mesmo ponto que abriu.'],closing:['FECHA TUDO O QUE VOCÊ ABRIU!','Primeiro recoloque o acabamento. Depois feche o capô, a porta e o porta-malas. Depois confira a montagem e siga para a ativação.'],explosion:['…','A instalação tomou um rumo inesperado.'],success:['AINDA FALTA A ATIVAÇÃO!','Rastreador escondido e veículo fechado. Agora peça os testes e libere o acesso do cliente no Ato 3.']}[state.phase];
return `<aside class="side"><section class="cat-card"><div class="cat-head">${portrait('cat',state.phase==='success'?'happy':'calm')}<div><small>CAT / SUPERVISÃO</small><strong>${tips[0]}</strong></div></div><p>${tips[1]}</p></section><section class="order"><small>ORDEM DE SERVIÇO #002</small><h3>LT-32 PRO</h3><dl><div><dt>Cliente</dt><dd>${escape(context.client||'Anderson')}</dd></div><div><dt>Veículo</dt><dd>${escape(context.vehicle||'Veículo de treinamento')}</dd></div><div><dt>Serviço</dt><dd>Rastreador + bloqueio</dd></div>${context.appointment?`<div><dt>Agendado</dt><dd>${escape(context.appointment)}</dd></div>`:''}${place?`<div><dt>Local</dt><dd>${place.name}</dd></div>`:''}</dl></section><section class="reference"><div class="reference-head">CHICOTE DO LT-32 PRO <span>4 VIAS</span></div>${LEADS.map(l=>`<div class="lead-ref"><i style="--wire:${l.color}" class="${l.id==='ground'?'black':''}"></i><span>${l.name}</span><strong>${l.function}</strong></div>`).join('')}<p>Saída amarela → borne 86 do relé preparado. O 85 já recebe positivo.</p><button data-action="help" class="text-button">Ver instruções do aparelho ↗</button></section><p class="source-note">Manual LT32 PRO · v.04-082025 · pp. 8–10.<br>As cores e pontos do veículo são fictícios.</p></aside>`;}
function heading(kicker,title,description){return `<div class="scene-heading"><div><span class="eyebrow">${kicker}</span><h1 id="scene-title" tabindex="-1">${title}</h1><p>${description}</p></div><span class="model-badge">LT-32 PRO <i></i></span></div>`;}
function sceneCard(content,cap='VEÍCULO ABERTO / VISTA 2D'){return `<section class="scene-card"><header><span><i class="live-dot"></i> ${cap}</span><span>ANDERSON / INSTALADOR</span></header>${content}</section>`;}
function warning(){return `<div class="panel-warning"><b>!</b><div><strong>PROIBIDO INSTALAR NO PAINEL.</strong><span>Regra da Cat para este serviço. Não diga que ela não avisou.</span></div></div>`;}
function locationView(){return `${heading('01 / ESCOLHA DO LOCAL','Onde você vai instalar?','O carro já está aberto. Escolha um ponto discreto para o rastreador.')}${warning()}${sceneCard(carSvg(state))}<div class="location-options" role="group" aria-label="Locais do veículo">${LOCATIONS.map(l=>`<button data-action="location" data-id="${l.id}" class="location-option ${l.id==='dashboard'?'banned':''}"><b>${l.label}</b><span>${l.name}</span>${l.id==='dashboard'?'<small>PROIBIDO</small>':''}</button>`).join('')}</div>`;}
function wiringSvg(){const roles=Object.keys(ROLE_INFO);return `<svg class="wiring-svg" viewBox="0 0 1000 760" preserveAspectRatio="xMidYMid meet" aria-label="Emaranhado de doze cabos do veículo e quatro fios do rastreador"><rect width="1000" height="760" fill="#17282f"/><text x="25" y="28" class="wire-caption">ORIGEM / VEÍCULO</text><text x="960" y="28" text-anchor="end" class="wire-caption">CHICOTE / LT-32 PRO</text><rect x="12" y="48" width="246" height="677" rx="10" fill="#243940" stroke="#41565b"/>${state.wires.map(w=>{const root=roles.indexOf(w.role),sy=83+root*55,ey=87+state.wires.indexOf(w)*55,selected=state.selected===w.id,connected=Object.values(state.connections).includes(w.id),d=`M250 ${sy}C${420+w.bend} ${sy-100},${295-w.bend} ${730-sy},480 ${390+w.bend}S${585-w.bend} ${ey-85},650 ${ey}`;return `<g class="wire-route ${selected?'selected':''} ${connected?'connected':''}" data-action="select-wire" data-id="${w.id}" role="button" tabindex="0" aria-label="Traçar cabo ${w.letter}"><text x="25" y="${sy+4}" class="origin-label">${ROLE_INFO[w.role].label}</text><path d="${d}" class="wire-outline"/><path d="${d}" class="wire-line" stroke="${w.color}"/><path d="${d}" class="wire-hit"/><circle cx="650" cy="${ey}" r="18" fill="${selected?'#f4c35c':connected?'#6b9d72':'#253d44'}" stroke="${w.color}" stroke-width="3"/><text x="650" y="${ey+5}" text-anchor="middle" class="end-label">${connected?'✓':w.letter}</text></g>`;}).join('')}<g transform="translate(742 77) scale(.9)">${trackerSvg().replace(/^<svg[^>]*>|<\/svg>$/g,'')}</g>${LEADS.map((l,i)=>{const y=294+i*117,source=state.connections[l.id],wire=state.wires.find(w=>w.id===source),wy=wire?87+state.wires.indexOf(wire)*55:0;return `<g class="terminal ${source?'connected':''}" data-action="connect" data-id="${l.id}" role="button" tabindex="0" aria-label="Conectar ao fio ${l.name}"><path d="M${785+i*15} 177V${y-20}Q${785+i*15} ${y} 758 ${y}H718" fill="none" stroke="#0b181e" stroke-width="11"/><path d="M${785+i*15} 177V${y-20}Q${785+i*15} ${y} 758 ${y}H718" fill="none" stroke="${l.id==='ground'?'#3f444d':l.color}" stroke-width="6"/><circle cx="718" cy="${y}" r="17" fill="${source?'#587c57':'#1d343b'}" stroke="${l.color}" stroke-width="3"/><text x="811" y="${y+5}" class="terminal-label" fill="${l.color}">${l.name.toUpperCase()}${source?' ✓':''}</text>${wire?`<path class="made-connection" d="M650 ${wy}C692 ${wy},674 ${y},718 ${y}" fill="none" stroke="${l.color}" stroke-width="5"/>`:''}</g>`;}).join('')}<path id="drag-wire" class="drag-wire" d=""/></svg>`;}
function wiringView(){const selected=inspectWire(state,state.selected),count=Object.keys(state.connections).length;return `${heading('02 / LIGAÇÃO DOS FIOS','No meio desse emaranhado…','Examine o cabo do veículo e conecte ao fio certo do rastreador.')}${count===0?`<div class="wire-tutorial">Primeira conexão: toque em um cabo para ler a função e as duas medições. Depois escolha o fio correspondente do LT-32 PRO.${desk?.profile.id==='training'?' Exemplo: o vermelho pede positivo permanente, com 12,6 V nas duas posições da chave.':''}</div>`:''}${sceneCard(wiringSvg(),`MESA DE LIGAÇÃO / ${count} DE 4 CONEXÕES`)}<div class="wire-controls"><section><div class="section-caption">1. ESCOLHA E EXAMINE UM CABO</div><div class="wire-choices">${state.wires.map(w=>{const used=Object.values(state.connections).includes(w.id);return `<button class="wire-choice ${state.selected===w.id?'selected':''} ${used?'used':''}" data-action="select-wire" data-id="${w.id}" ${used?'disabled':''} aria-label="Examinar cabo ${w.letter}"><i style="--wire:${w.color}"></i><strong>Cabo ${w.letter}</strong><span>${used?'✓ ligado':'medir ↗'}</span></button>`;}).join('')}</div><div class="probe" aria-live="polite">${selected?`<div class="probe-title"><span>MULTÍMETRO / CABO ${selected.letter}</span><strong>${selected.label}</strong></div><div class="probe-readings"><span>CHAVE DESLIGADA<b>${selected.off}</b></span><span>CHAVE LIGADA<b>${selected.on}</b></span></div><p>${selected.note}</p>`:'<div class="probe-empty"><b>Toque em um cabo para examinar.</b><span>A cor do fio do veículo não é suficiente. Confira a função.</span></div>'}</div></section><section><div class="section-caption">2. CONECTE AO CHICOTE</div><div class="terminal-choices">${LEADS.map(l=>{const wire=state.wires.find(w=>w.id===state.connections[l.id]);return `<button class="terminal-choice ${wire?'used':''}" data-action="connect" data-id="${l.id}" ${wire?'disabled':''} aria-label="Ligar ${l.name} do rastreador"><i style="--wire:${l.color}" class="${l.id==='ground'?'black':''}"></i><span><strong>${l.name}</strong><small>${l.function}</small></span><b>${wire?'✓ cabo '+wire.letter:'↗'}</b></button>`;}).join('')}</div><p class="wire-note">SIM já inserido com o aparelho desligado. Alimentação do veículo protegida por fusível de 2 A. Verde e azul do SOS ficam isolados nesta missão.</p></section></div>`;}
function hidingView(){const place=LOCATIONS.find(l=>l.id===state.location);return `${heading('03 / OCULTAÇÃO','Agora, faça ele desaparecer.','Nada de rastreador solto ou antena virada para baixo.')}${sceneCard(carSvg(state),`PONTO PREPARADO / ${place.name.toUpperCase()}`)}<section class="hide-controls"><div class="tracker-tray" draggable="false" data-tracker="true">${trackerSvg({up:state.antennaUp})}<small>${state.antennaUp?'FACE SEM ADESIVO PARA CIMA ✓':'FACE COM ADESIVO PARA CIMA'}</small></div><div class="hide-actions"><button data-action="flip" class="task-button ${state.antennaUp?'checked':''}"><b>${state.antennaUp?'✓':'1'}</b><span>Virar o rastreador<small>Deixe a face sem adesivo voltada para cima.</small></span></button><button data-action="secure" class="task-button ${state.secured?'checked':''}"><b>${state.secured?'✓':'2'}</b><span>Fixar e isolar<small>Prenda o aparelho e proteja as emendas.</small></span></button><div class="care-options"><button data-action="tidy" class="${state.tidy?'done':''}" ${state.tidy?'disabled':''}>${state.tidy?'✓ Chicote organizado':'Organizar e prender o chicote'}<small>Melhora a ocultação nos próximos atos.</small></button><button data-action="signal-check" class="${state.signalChecked?'done':''}" ${state.signalChecked?'disabled':''}>${state.signalChecked?'✓ Sinal conferido':'Conferir o sinal neste ponto'}<small>Ajuda a ativação e a recuperação.</small></button></div>${qualityNote()}<button class="btn primary" data-action="hide" data-id="${place.id}">Esconder ${place.id==='rear-trim'?'no':'na'} ${place.name.toLowerCase()} →</button></div></section>`;}
const partNames={trim:'Recolocar o acabamento',hood:'Fechar o capô',door:'Fechar a porta',trunk:'Fechar o porta-malas'};
function closingView(){const count=4-state.openParts.length;return `${heading('04 / ACABAMENTO','Parece que ninguém passou por aqui.','Recoloque o acabamento antes de fechar o veículo. Confira tudo antes de iniciar a ativação.')}${sceneCard(carSvg(state),`ACABAMENTO / ${count} DE 4 PEÇAS FECHADAS`)}<div class="closing-actions">${Object.entries(partNames).map(([id,name])=>`<button class="task-button ${state.openParts.includes(id)?'':'checked'}" data-action="close" data-id="${id}" ${!state.openParts.includes(id)?'disabled':''}><b>${state.openParts.includes(id)?'○':'✓'}</b><span>${name}</span></button>`).join('')}</div><div class="delivery-bar"><span>${count===4?'Tudo fechado. O rastreador ficou escondido.':`Faltam ${4-count} peça(s). Primeiro o acabamento.`}</span><button class="btn primary" data-action="deliver">Conferir instalação física ✓</button></div>`;}
function successView(){return `<section class="success"><span class="success-stamp">ATO 02 / CONCLUÍDO</span><h1>INSTALADO. ESCONDIDO.<br>FALTA ATIVAR.</h1><p>A instalação física passou. O técnico já está chamando você no WhatsApp.</p>${sceneCard(carSvg(state,{interactive:false}),'LT-32 PRO / INSTALAÇÃO FÍSICA APROVADA')}${qualityNote()}<div class="success-checks"><span>✓ 4 fios corretos</span><span>✓ Antena para cima</span><span>✓ Rastreador fixado</span><span>✓ Veículo fechado</span></div><div class="success-buttons"><button class="btn primary" data-action="activate">Continuar para a ativação →</button><button class="btn secondary" data-action="menu">Voltar ao início</button></div></section>`;}
function render(){if(!state)return;document.body.classList.toggle('reduce-motion',!!context.prefs?.reduceMotion);const content=({location:locationView,wiring:wiringView,hiding:hidingView,closing:closingView,success:successView,explosion:()=>`${heading('ERRO NA INSTALAÇÃO','Isso não estava na ordem de serviço.','…')}${sceneCard(carSvg(state,{interactive:false}),'FALHA / VEÍCULO AVARIADO')}`}[state.phase])();app.innerHTML=header()+`<main class="game-main">${desk?.markup(state.phase)||''}${progress()}<div class="layout"><section class="play-area">${content}</section>${sidebar()}</div><footer class="footer">OS ANDERSONS · INSTALANDO E ROUBANDO<span>Explosão é efeito do jogo. Pontos e cabos do veículo são fictícios.</span></footer></main>`;}
function change(action){if(!state||showFired)return;if(action.type==='connect'&&!state.selected){toast('Primeiro, toque em um cabo do veículo para examinar.');return;}desk?.checkpoint(state);const old=state.phase,next=applyAction(state,action);if(next===state)return;state=next;desk?.record(action.type+':'+(action.id||''),{progress:!['select-wire','flip','secure'].includes(action.type)});if(state.phase==='explosion'){startFailure();return;}save();render();if(old!==state.phase){window.scrollTo(0,0);$('#scene-title')?.focus({preventScroll:true});}if(['connect','close','hide'].includes(action.type))audio.tick(state.phase==='success');if(state.phase==='success'){desk?.finish();tellParent('installation',installationSummary(state));tellParent('complete',{phase:'finish',installationLocation:state.location});}else tellParent('progress',{phase:state.phase});}
function startFailure(){desk?.fail();try{localStorage.removeItem(key());}catch{}tellParent('failed',{phase:'explosion'});render();window.scrollTo(0,0);audio.boom();failTimeout=setTimeout(fired,context.prefs?.reduceMotion?450:1800);}
function fired(){showFired=true;focusBefore=document.activeElement;app.inert=true;modal.innerHTML=`<div class="modal-backdrop"><section class="fired-dialog" role="dialog" aria-modal="true" aria-labelledby="fired-title"><div class="failure-face">${portrait('cat','angry')}</div><div><span class="eyebrow">A CAT VIU TUDO.</span><h2 id="fired-title">MEU DEUS...!<br>ESTÁ DEMITIDO</h2><p>${escape(state.failure)}</p>${desk?.retryButton()||''}<button class="btn danger" data-action="menu">Voltar ao início →</button><small>${desk?.canRetry?'O checkpoint preservou seu trabalho. A explosão entra na avaliação.':'Contrato de experiência: o expediente acabou.'}</small></div></section></div>`;modal.querySelector('button').focus();let seconds=12;if(!desk?.canRetry)failInterval=setInterval(()=>{seconds--;const el=$('#fired-seconds');if(el)el.textContent=seconds;if(seconds<=0)exit();},1000);}
function exit(event='menu'){save();clearTimeout(failTimeout);clearInterval(failInterval);if(parent===window)location.href='./';else tellParent(event);}
function showHelp(){focusBefore=document.activeElement;app.inert=true;modal.innerHTML=`<div class="modal-backdrop"><section class="help-dialog" role="dialog" aria-modal="true" aria-labelledby="help-title"><header><div><span class="eyebrow">LEITURA RÁPIDA / LT-32 PRO</span><h2 id="help-title">O básico para não ser demitido.</h2></div><button data-action="close-help">Fechar</button></header><ol><li><strong>Local:</strong> painel proibido por ordem da Cat. Use um dos pontos plásticos discretos deste veículo fictício.</li><li><strong>Fios:</strong> examine os cabos A–L; clique no fio do chicote ou arraste entre as pontas. A cor do veículo não determina a função.</li><li><strong>Esconder:</strong> face sem adesivo para cima, sem metal cobrindo. Fixe o equipamento e isole as emendas.</li><li><strong>Fechar:</strong> primeiro o acabamento, depois capô, porta e porta-malas. Confira antes da entrega.</li></ol><div class="help-reference">${LEADS.map(l=>`<p><b style="color:${l.color}">${l.name}</b> · ${l.detail}</p>`).join('')}</div><p class="help-note">No manual: SIM só deve ser inserido ou retirado com o equipamento desligado. O conector de duas vias verde/azul é do botão SOS e não é usado nesta missão. Referência: manual LT32 PRO v.04-082025, páginas 8–10.</p><button class="btn primary" data-action="close-help">Entendi. Vamos instalar. →</button></section></div>`;modal.querySelector('button').focus();}
function closeHelp(){modal.innerHTML='';app.inert=false;if(focusBefore?.isConnected)focusBefore.focus();}
function dispatch(action,id){if(action==='retry-checkpoint')return retryInstallation();if(['location','select-wire','connect','flip','secure','tidy','signal-check','hide','close','deliver'].includes(action))return change({type:action,id});if(action==='activate'&&state.phase==='success'){if(parent===window)location.href='./activation.html';else tellParent('activate',{installationLocation:state.location});return;}if(action==='menu')return exit();if(action==='new-case')return exit('new-case');if(action==='help'&&!showFired)return showHelp();if(action==='close-help')return closeHelp();if(action==='sound'){if(parent===window){context.prefs.sound=context.prefs.sound===false;render();}else tellParent('sound');}}
for(const root of [app,modal])root.addEventListener('click',event=>{if(Date.now()<ignoreClickUntil)return;const el=event.target.closest('[data-action]');if(el&&!el.disabled){event.preventDefault();dispatch(el.dataset.action,el.dataset.id);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&modal.children.length&&!showFired){event.preventDefault();closeHelp();return;}if(['Enter',' '].includes(event.key)&&event.target.matches('g[data-action]')){event.preventDefault();dispatch(event.target.dataset.action,event.target.dataset.id);}if(modal.children.length&&event.key==='Tab'){const buttons=[...modal.querySelectorAll('button')],first=buttons[0],last=buttons.at(-1);if(event.shiftKey&&document.activeElement===first){last.focus();event.preventDefault();}else if(!event.shiftKey&&document.activeElement===last){first.focus();event.preventDefault();}}});
app.addEventListener('pointerdown',event=>{const cable=event.target.closest('[data-action="select-wire"]');if(!cable||state.phase!=='wiring'||Object.values(state.connections).includes(cable.dataset.id))return;drag={id:cable.dataset.id,x:event.clientX,y:event.clientY,moved:false};});
document.addEventListener('pointermove',event=>{if(!drag)return;if(Math.hypot(event.clientX-drag.x,event.clientY-drag.y)>10)drag.moved=true;if(!drag.moved)return;const svg=$('.wiring-svg'),line=$('#drag-wire');if(!svg||!line)return;const point=new DOMPoint(event.clientX,event.clientY).matrixTransform(svg.getScreenCTM().inverse()),wire=state.wires.find(w=>w.id===drag.id),y=87+state.wires.indexOf(wire)*55;line.setAttribute('d',`M650 ${y}Q${point.x} ${y} ${point.x} ${point.y}`);event.preventDefault();},{passive:false});
document.addEventListener('pointerup',event=>{if(!drag)return;const active=drag;drag=null;$('#drag-wire')?.setAttribute('d','');if(!active.moved)return;ignoreClickUntil=Date.now()+200;const target=document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-action="connect"]');if(target){state=applyAction(state,{type:'select-wire',id:active.id});change({type:'connect',id:target.dataset.id});}});
document.addEventListener('pointercancel',()=>{drag=null;$('#drag-wire')?.setAttribute('d','');});
window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden){save();audio.ctx?.suspend().catch(()=>{});}else if(context?.prefs?.sound!==false)audio.ctx?.resume().catch(()=>{});});
function initialize(payload){context={...payload,prefs:payload.prefs||{}};if(booted){desk?.updateContext(context);if(!showFired)render();return;}desk=new ShiftSession({act:2,context,tell:tellParent});let raw=null;try{raw=JSON.parse(localStorage.getItem(key()));}catch{}const retryRaw=desk.pendingRetry&&desk.canRetry?desk.retry():desk.snapshot;state=restoreInstallation(raw,context.caseId)||restoreInstallation(retryRaw,context.caseId)||createInstallation(context.caseId,hashCase(context.caseId));booted=true;desk.checkpoint(state);if(state.phase==='success')desk.finish();render();save();if(state.phase==='success')tellParent('installation',installationSummary(state));tellParent(state.phase==='success'?'complete':'progress',{phase:state.phase==='success'?'finish':state.phase,installationLocation:state.location});}
window.addEventListener('message',event=>{if(event.source!==parent||event.origin!==location.origin||event.data?.type!=='andersons-context'||!event.data.payload?.caseId)return;initialize(event.data.payload);});
tellParent('ready');if(parent===window)initialize({caseId:'lt32-standalone-'+Date.now().toString(36),mode:'lt32-free',client:'Anderson',vehicle:'Veículo de treinamento',prefs:{sound:true,reduceMotion:matchMedia('(prefers-reduced-motion: reduce)').matches}});

function qualityNote(){const q=installationSummary(state);return `<div class="installation-effect"><strong>QUALIDADE DA INSTALAÇÃO: ${q.quality}%</strong><br>Ocultação ${q.concealment}% · Sinal ${q.signal}%<br>${state.tidy?'Chicote organizado.':'Organizar o chicote melhora o esconderijo.'} ${state.signalChecked?'Sinal conferido: a ativação receberá essa informação.':'Conferir o sinal melhora a resposta nas fases seguintes.'}</div>`;}
function retryInstallation(){if(!desk?.canRetry)return;const next=restoreInstallation(desk.retry(),context.caseId);if(!next)return;clearTimeout(failTimeout);clearInterval(failInterval);showFired=false;modal.innerHTML='';app.inert=false;state=next;render();save();tellParent('progress',{phase:state.phase});window.scrollTo(0,0);}
setInterval(()=>{const now=performance.now(),ms=now-deskTick;deskTick=now;if(booted&&!document.hidden&&!modal.children.length&&!['explosion','success'].includes(state.phase))desk?.step(ms,state.phase);},500);
